def __post_init__(self):
        # Input Validations:
        if not isinstance(self.formatted_date, str) or len(self.formatted_date) > 10:
            raise ValueError("formatted_date must be a string of max length 10")
        if not isinstance(self.formatted_amount, str) or len(self.formatted_amount) > 19:
            raise ValueError("formatted_amount must be a string of max length 19")
        if not isinstance(self.formatted_rate, str) or len(self.formatted_rate) > 6:
            raise ValueError("formatted_rate must be a string of max length 6")
        if not isinstance(self.formatted_count, str) or len(self.formatted_count) > 10:
            raise ValueError("formatted_count must be a string of max length 10")
        if not isinstance(self.formatted_pct, str) or len(self.formatted_pct) > 5:
            raise ValueError("formatted_pct must be a string of max length 5")

