    """
    """
    logger.info("Starting the policy issuance process...")
    try:
        global ws_uw_decision
        if ws_uw_decision != 'DECLINE':
            generate_policy_number_C8()
            create_policy_record_C8()
            set_beneficiaries_C8()
            send_policy_docs_C8()
        else:
            send_decline_letter_C8()
        logger.info("Policy issuance process completed successfully.")
    except Exception as e:
        logger.error(f"Policy issuance process failed: {e}")
        raise

