def apply_stop_fee_C12(
    ws_stop_payment_fee: Decimal,
    ws_account_balance: Decimal
) -> None:
    """
    Applies the stop payment fee to the account balance
    This function subtracts the stop payment fee from the account balance, updates the account,
    sets the notification type and channel, and sends a notification
    Args:
        ws_stop_payment_fee: Stop payment fee amount
        ws_account_balance: Current account balance
        
    Returns:
        None
        
    Raises:
        ValueError: If ws_stop_payment_fee is negative
        
    Example:
        >>> apply_stop_fee(Decimal('5.00'), Decimal('100.00'))
    """
    logger.info("Applying stop payment fee")
    
    # Input validation
    if not isinstance(ws_stop_payment_fee, Decimal):
        logger.error(f"Invalid type for ws_stop_payment_fee: {type(ws_stop_payment_fee)}")
        raise ValueError(f"ws_stop_payment_fee must be a Decimal, got {type(ws_stop_payment_fee)}")
    
    if ws_stop_payment_fee < Decimal('0'):
        logger.error(f"Negative stop payment fee is not allowed: {ws_stop_payment_fee}")
        raise ValueError(f"Stop payment fee cannot be negative: {ws_stop_payment_fee}")
    
    if not isinstance(ws_account_balance, Decimal):
        logger.error(f"Invalid type for ws_account_balance: {type(ws_account_balance)}")
        raise ValueError(f"ws_account_balance must be a Decimal, got {type(ws_account_balance)}")

    try:
        global ws_account_balance_C12, ws_notif_type_C12, ws_notif_channel_C12, ws_notif_subject_C12, ws_check_number_C12
        
        # Subtract fee from account balance
        ws_account_balance_C12 = ws_account_balance - ws_stop_payment_fee
        logger.debug(f"Subtracted fee from account balance, new balance: {ws_account_balance_C12}")
        
        # Update account
        update_account_C12()
        
        ws_notif_type_C12 = 'stop_payment'
        logger.debug("Set ws_notif_type to 'stop_payment'")
        
        ws_notif_channel_C12 = 'EMAIL'
        logger.debug("Set ws_notif_channel to 'EMAIL'")
        
        # Create notification subject
        ws_notif_subject_C12 = f"Stop payment placed on check # {str(ws_check_number_C12)}"
        logger.debug(f"Created notification subject: {ws_notif_subject_C12}")
        
        # Send notification
        send_notification_C12()
        logger.info("Stop payment fee application completed")
    
    except Exception as e:
        logger.error(f"Stop payment fee application failed: {e}")
        raise

