        if not isinstance(self.ws_model_status, str) or len(self.ws_model_status) > 10:
            raise ValueError("ws_model_status must be a string of max length 10")
        if not isinstance(self.ws_validation_date, str) or len(self.ws_validation_date) != 8:
            raise ValueError("ws_validation_date must be a string of length 8")
        if not isinstance(self.ws_next_validation, str) or len(self.ws_next_validation) != 8:
            raise ValueError("ws_next_validation must be a string of length 8")
        if not isinstance(self.ws_overall_rating, str) or len(self.ws_overall_rating) > 1:
            raise ValueError("ws_overall_rating must be a string of max length 1")

